// ─── File: ApiVersionDemo.java ───
// Runnable demo: same AccountService serves BOTH v1 (flat) and v2 (structured).
package com.bank.apiversion;

import java.math.BigDecimal;
import java.util.logging.*;

public class ApiVersionDemo {

    private static final Logger log = Logger.getLogger("ApiVersion");

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        handler.setLevel(Level.ALL);
        log.setUseParentHandlers(false);
        log.addHandler(handler);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        AccountService service = new AccountService();

        // v1 client (legacy mobile app): expects flat balance number.
        V1AccountController v1 = new V1AccountController(service);
        V1AccountResponse r1 = v1.getAccount("SAV2001");
        log.warning(() -> "V1 (DEPRECATED, Sunset=2027-06-30) → " + r1);

        // v2 client (new app): expects structured amount + currency.
        V2AccountController v2 = new V2AccountController(service);
        V2AccountResponse r2 = v2.getAccount("SAV2001");
        log.info(() -> "V2 → " + r2);
    }
}

// ─── model/Account.java (shared internal model) ───
class Account {
    final String accountId, holderName, branchCode, currency;
    final BigDecimal balance;
    Account(String id, String name, BigDecimal bal, String branch, String ccy) {
        this.accountId = id; this.holderName = name; this.balance = bal;
        this.branchCode = branch; this.currency = ccy;
    }
}

// ─── service/AccountService.java (ONE business logic, both versions reuse it) ───
class AccountService {
    Account findById(String id) {
        // Rajesh's savings account, multi-currency aware internally.
        return new Account("SAV2001", "Rajesh Kumar",
                new BigDecimal("1000000.00"), "NBIN-MUM-001", "INR");
    }
}

// ─── v1/V1AccountResponse.java (OLD flat shape; branchCode added as SAFE additive field) ───
class V1AccountResponse {
    String accountId, holderName, branchCode;
    BigDecimal balance;   // flat number — legacy clients depend on this
    @Override public String toString() {
        return "{id=" + accountId + ", name=" + holderName
                + ", balance=" + balance + ", branch=" + branchCode + "}";
    }
}

// ─── v1/V1AccountController.java ───
// @RestController @RequestMapping("/v1/accounts")  (annotations shown for Spring)
class V1AccountController {
    private final AccountService service;
    V1AccountController(AccountService service) { this.service = service; }

    // @GetMapping("/{id}") — also sets Deprecation + Sunset headers in Spring.
    V1AccountResponse getAccount(String id) {
        Account a = service.findById(id);
        V1AccountResponse r = new V1AccountResponse();
        r.accountId = a.accountId; r.holderName = a.holderName;
        r.balance = a.balance;            // flat number preserved for old clients
        r.branchCode = a.branchCode;      // additive optional field — safe
        return r;
    }
}

// ─── v2/V2AccountResponse.java (NEW structured multi-currency shape) ───
class V2AccountResponse {
    String accountId, holderName, branchCode;
    Money balance;    // structured: amount + currency (BREAKING vs v1 → new version)
    @Override public String toString() {
        return "{id=" + accountId + ", name=" + holderName
                + ", balance=" + balance + ", branch=" + branchCode + "}";
    }
}

class Money {
    BigDecimal amount; String currency;
    Money(BigDecimal amount, String currency) { this.amount = amount; this.currency = currency; }
    @Override public String toString() { return amount + " " + currency; }
}

// ─── v2/V2AccountController.java ───
// @RestController @RequestMapping("/v2/accounts")
class V2AccountController {
    private final AccountService service;
    V2AccountController(AccountService service) { this.service = service; }

    V2AccountResponse getAccount(String id) {
        Account a = service.findById(id);
        V2AccountResponse r = new V2AccountResponse();
        r.accountId = a.accountId; r.holderName = a.holderName;
        r.branchCode = a.branchCode;
        r.balance = new Money(a.balance, a.currency);   // structured representation
        return r;
    }
}

class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT %2$-7s %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
